      {
        "statement": "Ascending IT lists its address as 2128 N Devlin Way, Nampa, ID 83687.",
        "label": "fact",
        "sourceUrl": "https://ascending-it.com/",
        "quote": "2128 N Devlin Way, Nampa, ID 83687"
      },
      {
        "statement": "Ascending IT operates from the Boise area, serving businesses in the Treasure Valley and nationwide.",
        "label": "fact",
        "sourceUrl": "https://ascending-it.com/",
        "quote": "Based in Boise, serving businesses locally across the Treasure Valley and nationwide."
      }
    ]
  },
  "industry": {
    "industry": "Information Technology / Managed IT Services & Cybersecurity",
    "activities": [
      "Managed IT Services",
      "Cybersecurity and Threat Protection",
      "Cloud and SaaS Management",
      "Backup and Disaster Recovery",
      "IT Infrastructure and Endpoint Management",
      "Co-Managed IT Services",
      "Compliance and vCIO Strategic IT Planning"
    ],
    "claims": [
      {
        "statement": "Ascending IT provides proactive IT management and cybersecurity solutions for small to medium businesses.",
        "label": "fact",
        "sourceUrl": "https://ascending-it.com/",
        "quote": "With 20+ years of experience, Ascending IT delivers proactive IT management and built-in cybersecurity for small to medium businesses across the Treasure Valley."
      },
      {
        "statement": "The company delivers 24/7 monitoring, proactive maintenance, and IT support services.",
        "label": "fact",
        "sourceUrl": "https://ascending-it.com/",
        "quote": "Our Boise Managed IT Services provide 24/7 monitoring, proactive maintenance, and fast support to reduce downtime, control costs, and keep your business running."
      }
    ]
  },
  "publicInformation": {
    "officialWebsite": "https://ascending-it.com/",
    "claims": [
      {
        "statement": "Ascending IT was founded on the philosophy that technology should function as an asset rather than a burden.",
        "label": "fact",
        "sourceUrl": "https://ascending-it.com/boise-it-company/",
        "quote": "Ascending IT was founded with a simple belief: IT should be an asset, not a burden."
      },
      {
        "statement": "Ascending IT structures its managed IT service packages with built-in cybersecurity.",
        "label": "fact",
        "sourceUrl": "https://ascending-it.com/",
        "quote": "Every plan includes built-in cybersecurity and scales with you as your business evolves."
      }
    ]
  },
  "licensing": {
    "claims": [
      {
        "statement": "Ascending IT supports client compliance frameworks including HIPAA and PCI-DSS, but displays no trade licenses or state registration numbers.",
        "label": "fact",
        "sourceUrl": "https://ascending-it.com/boise-it-company/",
        "quote": "From HIPAA to PCI-DSS, and cybersecurity threats to scaling challenges, we provide proactive solutions that give you clarity and confidence."
      }
    ],
    "limitations": "No specific corporate entity registration numbers (such as an Idaho Secretary of State filing number) or specialty trade licenses are published on the website."
  },
  "existingSoftware": [
    {
      "product": "IT Client Portal",
      "purpose": "Customer support ticket status tracking and ticketing management",
      "evidence": {
        "statement": "The website provides an external resource link for clients to check ticket status.",
        "label": "fact",
        "sourceUrl": "https://ascending-it.com/",
        "quote": "View Ticket Status"
      }
    },
    {
      "product": "ConnectBooster",
      "purpose": "Client invoice payment and billing portal",
      "evidence": {
        "statement": "The website provides a client payment portal linking to a ConnectBooster host.",
        "label": "fact",
        "sourceUrl": "https://ascending-it.com/",
        "quote": "Make A Payment"
      }
    },
    {
      "product": "Fluent Form",
      "purpose": "Form processing and lead capture for contact inquiries and assessment requests",
      "evidence": {
        "statement": "The website loads Fluent Form scripts to handle form submissions.",
        "label": "inference",
        "sourceUrl": "https://ascending-it.com/it-support-boise/",
        "quote": null
      }
    },
    {
      "product": "WordPress / Divi Theme",
      "purpose": "Website content management and layout delivery",
      "evidence": {
        "statement": "The website loads Divi theme assets and WordPress core libraries.",
        "label": "inference",
        "sourceUrl": "https://ascending-it.com/",
        "quote": null
      }
    },
    {
      "product": "Termageddon",
      "purpose": "Dynamic embedding of legal terms and privacy policies",
      "evidence": {
        "statement": "Terms and privacy policies load dynamic script embeds from Termageddon.",
        "label": "inference",
        "sourceUrl": "https://ascending-it.com/terms/",
        "quote": null
      }
    }
  ],
  "opportunityEvidence": [
    {
      "statement": "Ascending IT bills on flat-rate monthly managed IT plans, with pricing determined by user counts and assessment scoping.",
      "label": "fact",
      "sourceUrl": "https://ascending-it.com/managed-it-support-boise/",
      "quote": "We keep costs simple with flat-rate monthly pricing, so you always know what to expect."
    },
    {
      "statement": "Ascending IT serves commercial B2B clients across diverse industries rather than residential home-service trade customers.",
      "label": "inference",
      "sourceUrl": "https://ascending-it.com/",
      "quote": null
    }
  ],
  "problems": [
    {
      "problem": "Company operates in the B2B managed IT services sector, completely outside ForgeX's target residential trade contractor vertical.",
      "label": "inference",
      "basis": "Ascending IT provides IT infrastructure, cybersecurity, and cloud management to corporate clients, rather than residential HVAC, plumbing, or electrical contracting services."
    },
    {
      "problem": "Prospective clients cannot purchase or see pricing online directly without requesting a custom IT assessment.",
      "label": "hypothesis",
      "basis": "All service package exploration directs users to request a free assessment or contact sales, standard for MSP sales cycles."
    }
  ],
  "existingSolutions": [
    {
      "solution": "ConnectBooster billing portal and IT Client Portal ticketing system",
      "addresses": "Client invoicing, payments, and helpdesk support ticketing workflows",
      "alreadyOwned": true
    },
    {
      "solution": "Fluent Form lead intake workflows on WordPress",
      "addresses": "Free assessment scheduling and customer inbound contact requests",
      "alreadyOwned": true
    }
  ],
